CREATE COLUMN TABLE "TEST_AP"."OBGT" ("AbsId" INTEGER CS_INT NOT NULL , "AcctCode" NVARCHAR(15) NOT NULL , "BgdCode" INTEGER CS_INT, "FatherCode" NVARCHAR(15), "FthrPrcnt" DECIMAL(21,6) CS_FIXED, "DebLTotal" DECIMAL(21,6) CS_FIXED, "CredLTotal" DECIMAL(21,6) CS_FIXED, "DebSTotal" DECIMAL(21,6) CS_FIXED, "CredSTotal" DECIMAL(21,6) CS_FIXED, "DebRLTotal" DECIMAL(21,6) CS_FIXED, "CrdRLTotal" DECIMAL(21,6) CS_FIXED, "DebRSTotal" DECIMAL(21,6) CS_FIXED, "CrdRSTotal" DECIMAL(21,6) CS_FIXED, "FtrIDRLSum" DECIMAL(21,6) CS_FIXED, "FtrIDRSSum" DECIMAL(21,6) CS_FIXED, "FtrICRLSum" DECIMAL(21,6) CS_FIXED, "FtrICRSSum" DECIMAL(21,6) CS_FIXED, "FtrODRLSum" DECIMAL(21,6) CS_FIXED, "FtrOCRLSum" DECIMAL(21,6) CS_FIXED, "FtrODRSSum" DECIMAL(21,6) CS_FIXED, "FtrOCRSSum" DECIMAL(21,6) CS_FIXED, "FinancYear" LONGDATE CS_LONGDATE NOT NULL , "Instance" INTEGER CS_INT DEFAULT 1 NOT NULL , "UserSign" SMALLINT CS_INT, "SCNCounter" SMALLINT CS_INT, PRIMARY KEY ("AbsId")) UNLOAD PRIORITY 0  AUTO MERGE ;
